WITH lines AS (SELECT id, customer_id, EXPLODE(coupon_codes) AS tag FROM carts) SELECT tag, customer_id, SIZE(COLLECT_SET(tag)) AS num_tags, COUNT_IF(tag = 'BUNDLE') AS bundle_events, COUNT_IF(tag = 'BUNDLE') AS bundle_events_2, COUNT(*) AS event_count, COUNT(DISTINCT customer_id) AS distinct_customer_ids, SIZE(COLLECT_SET(tag)) AS num_tags_2, GROUPING(tag) AS gid FROM lines GROUP BY GROUPING SETS ((tag, customer_id), (tag))
